import datetime
from typing import Optional
import uuid
from sqlalchemy import (
    CheckConstraint,
    DateTime,
    SmallInteger,
    Text,
    func,
    text,
)
from sqlalchemy.dialects.postgresql import UUID
from sqlalchemy.orm import Mapped, mapped_column
from app.db.session import Base


class Approval(Base):
    __tablename__ = "approvals"

    # Unique approval identifier generated by PostgreSQL
    id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True),
        primary_key=True,
        server_default=text("gen_random_uuid()"),
    )

    # User ID from Neon Auth token (indexed for user isolation lookups)
    user_id: Mapped[str] = mapped_column(Text, nullable=False, index=True)

    # The post to be approved (one approval per post)
    post_id: Mapped[uuid.UUID] = mapped_column(
        UUID(as_uuid=True), nullable=False, unique=True
    )

    # Notification channel (email or whatsapp)
    channel: Mapped[str] = mapped_column(
        Text, nullable=False, server_default="email"
    )

    # SHA-256 hash of the 32-byte URL-safe approval token (raw token is never saved)
    token_hash: Mapped[str] = mapped_column(Text, nullable=False, unique=True)

    # Approval deadline matching the post publish_at timestamp
    expires_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False
    )

    # Number of email send attempts
    send_attempts: Mapped[int] = mapped_column(
        SmallInteger, nullable=False, server_default="0"
    )

    # Timestamp when the notification was successfully sent
    sent_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    # Short error message if the send failed (no personal text or tokens)
    send_error: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Final decision made by the user: approved or rejected
    decision: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Timestamp when the decision was recorded
    decided_at: Mapped[Optional[datetime.datetime]] = mapped_column(
        DateTime(timezone=True), nullable=True
    )

    # Source of the decision: email_link or dashboard
    decided_via: Mapped[Optional[str]] = mapped_column(Text, nullable=True)

    # Creation timestamp
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, server_default=func.now()
    )

    __table_args__ = (
        CheckConstraint(
            "channel IN ('email', 'whatsapp')",
            name="ck_approvals_channel",
        ),
        CheckConstraint(
            "decision IN ('approved', 'rejected')",
            name="ck_approvals_decision",
        ),
        CheckConstraint(
            "decided_via IN ('email_link', 'dashboard', 'slack')",
            name="ck_approvals_decided_via",
        ),
    )
